// Package migrations embeds the goose migration files applied at startup.
//
// Files are generated by `task migrate:diff NAME=<change>` from the ent schema
// (ADR-0009). Hand-written files are allowed for what Atlas cannot express
// (extensions, privileges); `task migrate:diff` rehashes atlas.sum around them.
// Migrations are additive only (expand); narrowing (contract) waits for a later
// release (SAD §10).
package migrations

import "embed"

// FS holds the *.sql goose migrations.
//
//go:embed *.sql
var FS embed.FS
